.version 8.7
.target sm_120
.address_size 64

.visible .entry groupnorm(
    .param .u64   param_input,      // fp16 input tensor
    .param .u64   param_weight,    // fp16 weight [C]
    .param .u64   param_bias,      // fp16 bias   [C]
    .param .u64   param_output,    // fp16 output tensor
    .param .u32   param_N,         // batch size
    .param .u32   param_C,         // channel count
    .param .u32   param_G,         // number of groups
    .param .u32   param_S,         // spatial size (product of remaining dims)
    .param .f32   param_eps        // epsilon
)
{
    // ---------- registers ----------
    .reg .pred   %p<10>;
    .reg .b32    %r<64>;
    .reg .b64    %rd<40>;
    .reg .f32    %f<64>;
    .reg .f16    %h<8>;

    // ---------- load parameters ----------
    ld.param.u64    %rd1, [param_input];
    ld.param.u64    %rd2, [param_weight];
    ld.param.u64    %rd3, [param_bias];
    ld.param.u64    %rd4, [param_output];
    ld.param.u32    %rN,  [param_N];
    ld.param.u32    %rC,  [param_C];
    ld.param.u32    %rG,  [param_G];
    ld.param.u32    %rS,  [param_S];
    ld.param.f32    %f_eps, [param_eps];

