    mov.u32         %r_ctaid_x, %ctaid.x;   // blockIdx.x
    mov.u32         %r_tid_x,   %tid.x;    // threadIdx.x
    mov.u32         %r_ntid_x,  %ntid.x;   // blockDim.x

    // ---------- derive (n, g) for this block ----------
    // g = blockIdx.x % G
    // n = blockIdx.x / G
    rem.u32         %r_g, %r_ctaid_x, %rG;
    div.u32         %r_n, %r_ctaid_x, %rG;

    // channels per group
    div.u32         %r_cpg, %rC, %rG;          // C_per_group

    // total elements per group = C_per_group * S
    mul.lo.u32      %r_group_elems, %r_cpg, %rS;

    // ---------- shared memory ----------
    .shared .align 4 .b32 s_sum[256];
    .shared .align 4 .b32 s_sumsq[256];
    .shared .align 4 .b32 s_mean;
    .shared .align 4 .b32 s_invstd;

    // ---------- first pass: per‑thread sum & sum‑of‑squares ----------
    mov.f32         %f_sum,   0.0;
    mov.f32         %f_sumsq, 0.0;

    // i = tid; i < group_elems; i += blockDim.x
    mov.u32         %r_i, %r_tid_x;

