    div.u32         %r_co, %r_i, %rS;
    rem.u32         %r_so, %r_i, %rS;

    // channel index c = g * Cpg + channel_offset
    mad.lo.u32      %r_c, %r_g, %r_cpg, %r_co;

    // linear element index = ((n*C + c) * S) + spatial_offset
    mad.lo.u32      %r_nc, %r_n, %rC, %r_c;      // n*C + c
    mad.lo.u32      %r_idx, %r_nc, %rS, %r_so;  // element index

    // byte offset (fp16 => 2 bytes)
    mul.wide.u32    %rd_off, %r_idx, 2;

