    cvta.to.global.u64 %rd_in_ptr, %rd1;
    add.u64         %rd_addr, %rd_in_ptr, %rd_off;

    // load fp16, convert to f32
    ld.global.f16   %h0, [%rd_addr];
    cvt.f32.f16     %f0, %h0;

    // accumulate
    add.f32         %f_sum, %f_sum, %f0;
    mul.f32         %f_tmp, %f0, %f0;
    add.f32         %f_sumsq, %f_sumsq, %f_tmp;

    // i += blockDim.x
    add.u32         %r_i, %r_i, %r_ntid_x;
    bra.uni         $LOOP_SUM;
$END_SUM:

    // store per‑thread partial results in shared memory
    mul.lo.u32      %r_off, %r_tid_x, 4;
    st.shared.u32   [s_sum+%r_off], %f_sum;
    st.shared.u32   [s_sumsq+%r_off], %f_sumsq;

    // synchronize
    bar.sync 0;

    // ---------- reduction across block ----------
    // stride = blockDim.x / 2; loop while stride > 0
    mov.u32         %r_stride, %r_ntid_x;
    shr.u32         %r_stride, %r_stride, 1;

$REDUCE_LOOP:
    setp.eq.u32     %p1, %r_stride, 0;
    @%p1 bra        $REDUCE_DONE;

    setp.lt.u32     %p2, %r_tid_x, %r_stride;
    @%p2 {
