        ld.shared.u32 %r_a, [s_sum+%r_off];
        ld.shared.u32 %r_b, [s_sum+%r_off_p];
        add.u32     %r_c, %r_a, %r_b;
        st.shared.u32 [s_sum+%r_off], %r_c;

        // sumsq
        ld.shared.u32 %r_a2, [s_sumsq+%r_off];
        ld.shared.u32 %r_b2, [s_sumsq+%r_off_p];
        add.u32     %r_c2, %r_a2, %r_b2;
        st.shared.u32 [s_sumsq+%r_off], %r_c2;
    }
    bar.sync 0;
    shr.u32         %r_stride, %r_stride, 1;
    bra.uni         $REDUCE_LOOP;
$REDUCE_DONE:

    // thread 0 now holds totals in element 0
    ld.shared.f32   %f_total_sum, [s_sum];
    ld.shared.f32   %f_total_sumsq, [s_sumsq];

