    div.f32         %f_mean, %f_total_sum, %f_group_elems_f;

    // variance = (total_sumsq / N) - mean*mean
    div.f32         %f_mean_sq, %f_total_sumsq, %f_group_elems_f;
    mul.f32         %f_mean_sq2, %f_mean, %f_mean;
    sub.f32         %f_var, %f_mean_sq, %f_mean_sq2;

    // inv_std = rsqrt(var + eps)
    add.f32         %f_var_eps, %f_var, %f_eps;
    rsqrt.approx.f32 %f_invstd, %f_var_eps;

    // store mean & invstd in shared for all threads
    st.shared.f32   [s_mean], %f_mean;
    st.shared.f32   [s_invstd], %f_invstd;

    bar.sync 0;

    // reload mean & invstd
    ld.shared.f32   %f_mean_all, [s_mean];
    ld.shared.f32   %f_invstd_all, [s_invstd];

    // ---------- second pass: write normalized output ----------
    mov.u32         %r_i, %r_tid_x;

$LOOP_OUT:
    setp.ge.u32     %p3, %r_i, %r_group_elems;
    @%p3 bra        $END_OUT;

    // recompute indices (same as above)
    div.u32         %r_co, %r_i, %rS;
    rem.u32         %r_so, %r_i, %rS;
    mad.lo.u32      %r_c, %r_g, %r_cpg, %r_co;
    mad.lo.u32      %r_nc, %r_n, %rC, %r_c;
    mad.lo.u32      %r_idx, %r_nc, %rS, %r_so;

    // input address
    mul.wide.u32    %rd_off, %r_idx, 2;
    cvta.to.global.u64 %rd_in_ptr, %rd1;
    add.u64         %rd_addr_in, %rd_in_ptr, %rd_off;

    // load input fp16, convert to f32
    ld.global.f16   %h1, [%rd_addr_in];
    cvt.f32.f16     %f_x, %h1;

    // normalize
    sub.f32         %f_norm, %f_x, %f_mean_all;
    mul.f32         %f_norm, %f_norm, %f_invstd_all;

