    cvta.to.global.u64 %rd_w_ptr, %rd2;
    add.u64         %rd_addr_w, %rd_w_ptr, %rd_off_w;
    ld.global.f16   %h2, [%rd_addr_w];
    cvt.f32.f16     %f_w, %h2;

